export const getListFamilyMessagesUrl = (astronautId: string,
    params?: ListFamilyMessagesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/family/messages/${astronautId}?${stringifiedParams}` : `/api/family/messages/${astronautId}`
}

